exploreUrl:
@js:
var s=null;try{s=this.source||source}catch(e){}
var v={};try{v=JSON.parse(s.getVariable()||'{}')}catch(e){}
var cfg=v.__cfg||{},mode=(cfg.mode||'novel'),base='';
try{base=String(s.bookSourceUrl).replace(/\/$/,'')}catch(e){}
var srcs=[],tabs=[],out=[];
try{var j=JSON.parse(java.ajax(base+'/explore-tabs,'+JSON.stringify({method:'GET',headers:cfx.headers.call(this)})));if(j&&j.data){srcs=j.data.sources||[];tabs=j.data.tabs||[];var cur=j.data.current||{};mode=cur.mode||'novel';cfg.source=cur.source||'';cfg.mode=mode;v.__cfg=cfg;v.__csrc=cfg.source;}}catch(e){}
try{s.setVariable(JSON.stringify(v))}catch(e){}
if(srcs.length){var names=[],map={};for(var i=0;i<srcs.length;i++){names.push(srcs[i].name);map[srcs[i].name]=srcs[i].code;}
v.__srcmap=map;try{s.setVariable(JSON.stringify(v))}catch(e){}
var cur='全部平台',cs=cfg.source||'';for(var n in map){if(map[n]===cs)cur=n;}
var ML={novel:'小说',audio:'听书',comic:'漫画',video:'短剧'};
out.push({title:'源站',type:'select',chars:names,default:cur,action:"(function(){cfx.setSourceByName.call(this,infoMap['源站']||'')})()",style:{layout_flexGrow:1,layout_flexBasisPercent:0.55}});
out.push({title:'模式',type:'select',chars:[ML.novel,ML.audio,ML.comic,ML.video],default:ML[mode],action:"(function(){var m={};for(var k in ML)m[ML[k]]=k;cfx.setMode.call(this,m[infoMap['模式']]||'novel')})()",style:{layout_flexGrow:1,layout_flexBasisPercent:0.45}});}
if(!tabs.length){tabs=[{title:'发现',url:'/api/v1/bookstore/conflux/explore?source='+encodeURIComponent(cfg.source||'fanqie')+'&mode='+encodeURIComponent(mode)+'&page={'+'{page}}'}];}
for(var t=0;t<tabs.length;t++){out.push(tabs[t]);}
JSON.stringify(out);

loginUrl:
function ua(){try{return cfx.ua.call(this)}catch(x){return 'Mozilla/5.0'}}
function op(u,t){try{java.startBrowserAwait(u,t)}catch(x){try{java.startBrowser(u,t)}catch(y){}}}
function bs(){try{return cfx.lb.call(this)}catch(x){return ''}}
function tq(){try{return String((JSON.parse(source.getLoginHeader()||'{}')||{}).Authorization||'').replace('Bearer ','')}catch(x){return ''}}
function login(f){var e='',p='';try{if(f===true){e=result.get('邮箱')||'';p=result.get('密码')||''}else{var m=source.getLoginInfoMap();e=m.get('邮箱')||'';p=m.get('密码')||''}}catch(x){}if(!e||!p){java.toast('请填写邮箱密码');return}try{var j=JSON.parse(java.ajax(bs()+'/login,'+JSON.stringify({method:'POST',body:JSON.stringify({email:e,password:p}),headers:{'User-Agent':ua(),'X-Device-Id':cfx.did.call(this),'Content-Type':'application/json'}})));if(!(j.data&&j.data.token)){java.toast('登录失败：'+j.msg);return}source.putLoginHeader(JSON.stringify({Authorization:'Bearer '+j.data.token,'X-Session-Key':j.data.kid||'','X-Resp-Key':j.data.respKey||''}));var v={};try{v=JSON.parse(source.getVariable()||'{}')}catch(x){}v.__rk=j.data.respKey||'';v.__kid=j.data.kid||'';source.setVariable(JSON.stringify(v));try{java.upLoginData()}catch(x){}java.toast('已登录')}catch(x){java.toast('失败：'+x)}}
function logout(){try{java.ajax(bs()+'/logout,'+JSON.stringify({method:'POST',headers:cfx.headers.call(this)}))}catch(x){}try{source.removeLoginHeader()}catch(x){}java.toast('已退出登录')}
function upd(){op(bs()+'/update?v='+cfx.ver,'更新')}
function pg(p,t){var s=tq();op(bs()+p+(s?'?t='+encodeURIComponent(s):''),t)}
function settings(){pg('/settings','源站与段评')}
function register(){op(bs()+'/register','注册账号')}
function user(){op(bs()+'/u','用户中心')}
function icons(){op(bs()+'/icons-page','气泡样式')}
function status(){pg('/status','源状态')}
function web(){op(cfx.site,'网页端')}
